from __future__ import annotations

import base64
import io
from dataclasses import dataclass
from typing import Any, Dict, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


@dataclass
class ValidationResult:
    valid: bool
    fields: Dict[str, Any]
    confidences: Dict[str, float]
    missing_required_fields: list[str]
    low_confidence_fields: list[str]
    errors: list[str]


def _load_bytes(document: Any) -> bytes:
    if document is None:
        raise ValueError("document is required")

    if isinstance(document, bytes):
        return document

    if isinstance(document, bytearray):
        return bytes(document)

    if isinstance(document, str):
        if document.startswith("data:") and ";base64," in document:
            _, b64 = document.split(";base64,", 1)
            return base64.b64decode(b64)
        try:
            with open(document, "rb") as f:
                return f.read()
        except OSError:
            return document.encode("utf-8")

    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data

    raise TypeError("Unsupported document type")


def _as_float(value: Any) -> Optional[float]:
    try:
        if value is None:
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def _get_field_value(field: Any) -> Any:
    if field is None:
        return None

    if hasattr(field, "value"):
        try:
            return field.value
        except Exception:
            pass

    for attr in ("content", "text"):
        if hasattr(field, attr):
            try:
                return getattr(field, attr)
            except Exception:
                pass

    if isinstance(field, dict):
        for key in ("value", "content", "text"):
            if key in field:
                return field[key]

    return field


def _get_field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None

    if hasattr(field, "confidence"):
        return _as_float(getattr(field, "confidence"))

    if isinstance(field, dict) and "confidence" in field:
        return _as_float(field["confidence"])

    return None


def extract_and_validate_invoice_fields(
    document: Any,
    required_fields: Optional[list[str]] = None,
    confidence_threshold: float = 0.8,
    model_id: str = "prebuilt-invoice",
) -> ValidationResult:
    required_fields = required_fields or [
        "VendorName",
        "InvoiceDate",
        "InvoiceId",
        "Total",
    ]

    endpoint = __import__("os").environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = __import__("os").environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise EnvironmentError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set"
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    doc_bytes = _load_bytes(document)

    poller = client.begin_analyze_document(
        model_id,
        analyze_request=doc_bytes,
        content_type="application/octet-stream",
    )
    result = poller.result()

    extracted_fields: Dict[str, Any] = {}
    confidences: Dict[str, float] = {}
    missing_required_fields: list[str] = []
    low_confidence_fields: list[str] = []
    errors: list[str] = []

    documents = getattr(result, "documents", None) or []
    first_doc = documents[0] if documents else None
    doc_fields = getattr(first_doc, "fields", None) if first_doc else None
    doc_fields = doc_fields or {}

    for field_name in required_fields:
        field = None
        if isinstance(doc_fields, dict):
            field = doc_fields.get(field_name)
        else:
            field = getattr(doc_fields, field_name, None)

        value = _get_field_value(field)
        confidence = _get_field_confidence(field)

        if value is None or (isinstance(value, str) and not value.strip()):
            missing_required_fields.append(field_name)
            errors.append(f"Missing required field: {field_name}")
        else:
            extracted_fields[field_name] = value

        if confidence is None:
            confidence = 0.0

        confidences[field_name] = confidence
        if confidence < confidence_threshold:
            low_confidence_fields.append(field_name)
            errors.append(
                f"Low confidence for {field_name}: {confidence:.3f} < {confidence_threshold:.3f}"
            )

    valid = not missing_required_fields and not low_confidence_fields

    return ValidationResult(
        valid=valid,
        fields=extracted_fields,
        confidences=confidences,
        missing_required_fields=missing_required_fields,
        low_confidence_fields=low_confidence_fields,
        errors=errors,
    )
